function solve({config,state,event}){
  let s=state||{head:null,records:[]};
  let old=Array.isArray(s.records)?s.records:[], incoming=event.records||[], bad=false;
  function find(a,id){for(let i=0;i<a.length;i++)if(a[i].id===id)return a[i];return null}
  for(let i=0;i<incoming.length;i++){
    let r=incoming[i], x=find(incoming,r.id), y=find(old,r.id);
    if(x&& (x.p!==r.parent||x.v!==r.value))bad=true;
    if(y&& (y.p!==r.parent||y.v!==r.value))bad=true;
  }
  let graph=old;
  if(!bad){
    graph=old.slice();
    for(let i=0;i<incoming.length;i++){
      let r=incoming[i];
      if(!find(graph,r.id))graph.push({id:r.id,p:r.parent,v:r.value});
    }
  }
  function walk(start){
    let a=[],m=[],h=start;
    while(h!==null){
      a.push(h);
      let r=find(graph,h);
      if(!r){if(m.indexOf(h)<0)m.push(h);break}
      h=r.p;
    }
    if(h===null)a.push(null);
    return {a:a,m:m,end:h};
  }
  let local=s.head, remote=event.head, l=walk(local), r=walk(remote), miss=[];
  for(let q of l.m.concat(r.m))if(miss.indexOf(q)<0)miss.push(q);
  miss.sort();
  let head=local,decision;
  if(bad)decision='conflict';
  else if(local===remote)decision='same';
  else if(l.a.indexOf(remote)>=0)decision='ahead';
  else if(r.a.indexOf(local)>=0){decision='advance';head=remote}
  else if(l.end===null&&r.end===null)decision='fork';
  else decision='unknown';
  return {state:{head:head,records:graph},output:{head:head,decision:decision,missing:miss}};
}
